frame.setWorkspacePane(frame.workspace.initialPaneId,{label:'Activity layout fixture',component:Empty});frame.openView('notes');
(globalThis as typeof globalThis & {__viewBarTest:unknown}).__viewBarTest={frame,get notesMounts(){return notesMounts;}};
createApp({render:()=>h(FrameShell,{frame,showSearch:false})}).mount('#app');
